=== FILE: skid_buffer.v ===
// skid_buffer: two-register valid/ready register slice.
// Implements microarchitecture.md (state table section 2, next-state table section 3)
// for the interface in interface_spec.md.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats; only full while m_valid.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat is accepted on this edge.
    wire s_fire = s_valid && !skid_valid;

    // Registered ready: the inverse of a flop, independent of m_ready/s_valid.
    assign s_ready = !skid_valid;

    // Control registers, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else if (m_free) begin
            if (skid_valid) begin
                // Move the skid beat to the output register.
                m_valid    <= 1'b1;
                skid_valid <= 1'b0;
            end else begin
                // Load straight from the sender.
                m_valid    <= s_valid;
            end
        end else if (s_fire) begin
            // Output stalled: catch the beat already promised by s_ready.
            skid_valid <= 1'b1;
        end
    end

    // Data registers: not reset; each loads only in its control's row.
    always @(posedge clk) begin
        if (m_free) begin
            if (skid_valid) begin
                m_data <= skid_data;
            end else begin
                m_data <= s_data;
            end
        end else if (s_fire) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    // Design-intent assertions.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Start from reset.
    always @(*) if (!f_past_valid) assume(!rst_n);

    // The skid register is only full while the output register is full.
    always @(*) if (f_past_valid && skid_valid) assert(m_valid);

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                // Reset drops every held beat.
                assert(!m_valid);
                assert(!skid_valid);
            end else if ($past(m_valid) && !$past(m_ready)) begin
                // Hold: a stalled beat stays offered with the same data.
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
