// skid_buffer_tb: self-checking testbench for skid_buffer.
// Two lanes (WIDTH 8 and WIDTH 1) share one handshake stimulus and are checked
// every cycle against a reference queue of up to two beats.
`default_nettype none

module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire       m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    // Bookkeeping
    integer passed;
    integer failed;
    integer count;      // beats held by the reference model
    integer n_in;
    integer n_out;
    integer n_drop;
    integer i;
    integer k;
    integer s0;
    integer m0;
    integer seed;

    reg [7:0]  q0;
    reg [7:0]  q1;
    reg [7:0]  hold_data;
    reg [7:0]  md_pre;
    reg [7:0]  d_cap;
    reg [7:0]  ctr;
    reg [31:0] rnd;
    reg        checking;
    reg        hold_pending;
    reg        sf;
    reg        mf;
    reg        rc;
    reg        mv_pre;
    reg        mr_pre;
    reg        sr8_b;
    reg        sr1_b;
    reg        mv8_b;
    reg        mv1_b;
    reg        md1_b;
    reg [7:0]  md8_b;
    reg        done;
    reg [8*64-1:0] nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task check(input ok, input [8*64-1:0] msg);
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL at %0t: %0s", $time, msg);
            end
        end
    endtask

    // Compare both lanes with the reference queue.
    task check_outputs;
        begin
            check(m_valid8 === (count > 0), "m_valid (WIDTH 8) high exactly while beats held");
            check(m_valid1 === (count > 0), "m_valid (WIDTH 1) high exactly while beats held");
            check(s_ready8 === (count < 2), "s_ready (WIDTH 8) high exactly while <2 held");
            check(s_ready1 === (count < 2), "s_ready (WIDTH 1) high exactly while <2 held");
            if (count > 0) begin
                check(m_data8 === q0, "m_data (WIDTH 8) is the oldest held beat");
                check(m_data1 === q0[0], "m_data (WIDTH 1) is the oldest held beat");
            end
            if (count > 2) begin
                check(1'b0, "reference model holds more than two beats");
            end
            if (hold_pending) begin
                check(m_valid8 === 1'b1 && m_data8 === hold_data,
                      "hold: stalled beat stays offered with same data");
            end
        end
    endtask

    // One clock cycle. Called just after a rising edge, with inputs already set.
    task step;
        begin
            #1;
            check_outputs;
            // Glitch the inputs inside the cycle: no output may move.
            sr8_b = s_ready8;
            sr1_b = s_ready1;
            mv8_b = m_valid8;
            mv1_b = m_valid1;
            md8_b = m_data8;
            md1_b = m_data1;
            s_valid = ~s_valid;
            m_ready = ~m_ready;
            s_data  = ~s_data;
            #1;
            check(s_ready8 === sr8_b && s_ready1 === sr1_b,
                  "s_ready does not move with m_ready/s_valid in a cycle");
            check(m_valid8 === mv8_b && m_valid1 === mv1_b &&
                  m_data8 === md8_b && m_data1 === md1_b,
                  "registered outputs do not move with inputs in a cycle");
            s_valid = ~s_valid;
            m_ready = ~m_ready;
            s_data  = ~s_data;
            #1;
            // Sample the handshakes before the edge.
            sf     = s_valid & s_ready8;
            mf     = m_valid8 & m_ready;
            rc     = rst_n;
            d_cap  = s_data;
            mv_pre = m_valid8;
            mr_pre = m_ready;
            md_pre = m_data8;
            @(posedge clk);
            if (!rc) begin
                n_drop = n_drop + count;
                count = 0;
                hold_pending = 1'b0;
            end else begin
                if (mf) begin
                    if (count > 0) begin
                        q0 = q1;
                        count = count - 1;
                        n_out = n_out + 1;
                    end
                end
                if (sf) begin
                    if (count == 0) begin
                        q0 = d_cap;
                    end else if (count == 1) begin
                        q1 = d_cap;
                    end
                    count = count + 1;
                    n_in = n_in + 1;
                end
                hold_pending = mv_pre & ~mr_pre;
                hold_data = md_pre;
            end
            #1;
        end
    endtask

    task drain;
        begin
            s_valid = 1'b0;
            m_ready = 1'b1;
            k = 0;
            while (count > 0 && k < 8) begin
                step;
                k = k + 1;
            end
            check(count == 0 && m_valid8 === 1'b0 && m_valid1 === 1'b0,
                  "drain empties the slice");
        end
    endtask

    // Watchdog
    initial begin
        #1000000;
        if (!done) begin
            failed = failed + 1;
            $error("FAIL: simulation timeout");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end

    initial begin
        passed = 0;
        failed = 0;
        count = 0;
        n_in = 0;
        n_out = 0;
        n_drop = 0;
        seed = 32'h5eed1234;
        q0 = 8'h00;
        q1 = 8'h00;
        hold_data = 8'h00;
        hold_pending = 1'b0;
        checking = 1'b0;
        done = 1'b0;
        ctr = 8'h00;
        rst_n = 1'b0;
        s_valid = 1'b0;
        m_ready = 1'b0;
        s_data = 8'h00;
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = "none";
        end

        // ---- Reset values ----
        repeat (2) @(posedge clk);
        #1;
        checking = 1'b1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset: m_valid low");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset: s_ready high");
        step;
        rst_n = 1'b1;
        step;

        // ---- One-cycle latency ----
        m_ready = 1'b1;
        s_valid = 1'b1;
        s_data = 8'hA5;
        check(m_valid8 === 1'b0, "latency: nothing offered before acceptance");
        step;
        s_valid = 1'b0;
        check(m_valid8 === 1'b1 && m_data8 === 8'hA5 && m_data1 === 1'b1,
              "latency: beat offered on the cycle after acceptance");
        step;
        check(m_valid8 === 1'b0 && count == 0, "latency: beat left exactly once");

        // ---- Full throughput ----
        m_ready = 1'b1;
        s_valid = 1'b1;
        s0 = n_in;
        m0 = n_out;
        for (i = 0; i < 64; i = i + 1) begin
            s_data = ctr;
            ctr = ctr + 8'd1;
            check(s_ready8 === 1'b1, "full throughput: s_ready stays high");
            step;
        end
        check(n_in == s0 + 64, "full throughput: one beat in per edge");
        check(n_out == m0 + 63, "full throughput: one beat out per edge, no bubble");
        drain;

        // ---- Stall with one and with two beats held ----
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data = 8'h11;
        step;
        check(count == 1 && m_valid8 === 1'b1, "stall: one beat held");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1,
              "stall with one beat held: s_ready high");
        s_data = 8'h22;
        s0 = n_in;
        step;
        check(n_in == s0 + 1 && count == 2, "stall: second beat accepted");
        check(s_ready8 === 1'b0 && s_ready1 === 1'b0,
              "stall with two beats held: s_ready low");
        s_data = 8'h33;
        s0 = n_in;
        step;
        check(n_in == s0 && count == 2, "stall: third beat not accepted");
        // Hold rule while the sender changes its offer.
        for (i = 0; i < 6; i = i + 1) begin
            rnd = $random(seed);
            s_valid = rnd[0];
            s_data = rnd[15:8];
            step;
            check(m_data8 === 8'h11, "hold: stalled beat data unchanged");
        end
        // Ready rises after the stall.
        s_valid = 1'b0;
        m_ready = 1'b1;
        check(m_data8 === 8'h11, "after stall: oldest beat first");
        step;
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "after stall: s_ready rises");
        check(m_valid8 === 1'b1 && m_data8 === 8'h22, "after stall: second beat next");
        step;
        check(m_valid8 === 1'b0 && count == 0, "after stall: every beat out once");

        // ---- Stall then release with continuous traffic (no bubble) ----
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data = 8'h40;
        step;
        s_data = 8'h41;
        step;
        m_ready = 1'b1;
        s0 = n_out;
        for (i = 0; i < 8; i = i + 1) begin
            s_data = 8'h42 + i[7:0];
            step;
        end
        check(n_out == s0 + 8, "release after stall: one beat out per edge");
        drain;

        // ---- Random traffic against the model ----
        for (i = 0; i < 3000; i = i + 1) begin
            rnd = $random(seed);
            s_data = rnd[7:0];
            if (i < 1000) begin
                s_valid = rnd[8];
                m_ready = rnd[9];
            end else if (i < 2000) begin
                s_valid = (rnd[11:10] != 2'b00);
                m_ready = (rnd[13:12] == 2'b00);
            end else begin
                s_valid = (rnd[11:10] == 2'b00);
                m_ready = (rnd[13:12] != 2'b00);
            end
            step;
        end
        drain;
        check(n_in == n_out + n_drop, "every accepted beat left exactly once");

        // ---- Reset with beats held ----
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data = 8'h77;
        step;
        s_data = 8'h88;
        step;
        check(count == 2 && s_ready8 === 1'b0, "reset test: two beats held");
        rst_n = 1'b0;
        step;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset with beats held: m_valid low");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset with beats held: s_ready high");
        rst_n = 1'b1;
        s_valid = 1'b0;
        step;
        check(m_valid8 === 1'b0, "after reset: slice stays empty");
        m_ready = 1'b1;
        s_valid = 1'b1;
        s_data = 8'h5A;
        step;
        s_valid = 1'b0;
        check(m_valid8 === 1'b1 && m_data8 === 8'h5A && m_data1 === 1'b0,
              "after reset: new beat passes");
        step;
        check(m_valid8 === 1'b0 && count == 0, "after reset: beat left once");

        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
